from selenium.webdriver.common.by import By
from selenium.webdriver.remote.webdriver import WebDriver

class InventoryPage:
    def __init__(self, driver):
        self.driver = driver
        self.inventory_list = (By.CLASS_NAME, 'inventory_list')

    def is_inventory_displayed(self):
        return self.driver.find_element(*self.inventory_list).is_displayed()


    def __init__(self, driver: WebDriver):
        self.driver = driver
        self.inventory_items = (By.CLASS_NAME, 'inventory_item')
        self.cart_button = (By.CLASS_NAME, 'shopping_cart_link')


    def get_inventory_item_count(self):
        return len(self.driver.find_elements(*self.inventory_items))


    def go_to_cart(self):
        self.driver.find_element(*self.cart_button).click()

